export function latLonToMelbourneWorld(
  lat: number,
  lon: number
): [number, number] {
  const rawKmX = (lon - MELBOURNE_GEO_CONFIG.centerLon) * (MELBOURNE_GEO_CONFIG.kmPerDegLon ?? 90);
  const rawKmZ = -(lat - MELBOURNE_GEO_CONFIG.centerLat) * (MELBOURNE_GEO_CONFIG.kmPerDegLat ?? 111.1);
  const distKm = Math.hypot(rawKmX, rawKmZ);
  const coreRadiusKm = MELBOURNE_GEO_CONFIG.coreRadiusKm ?? 7.5;
  const worldUnitsPerKm = MELBOURNE_GEO_CONFIG.worldUnitsPerKm ?? 10.8;
  let effectiveKm = distKm;
  if (distKm > coreRadiusKm) {
    effectiveKm = coreRadiusKm + Math.log1p((distKm - coreRadiusKm) * 0.30) * 5.6;
  }
  const scale = distKm > 0.0001 ? (effectiveKm / distKm) * worldUnitsPerKm : worldUnitsPerKm;
  return [Math.round(rawKmX * scale * 100) / 100, Math.round(rawKmZ * scale * 100) / 100];
}

